const HASHED = (path) => /(^|\/)assets\/[^/]+-[\w-]{8,}(\.\w+)+$/.test(path);
const PAGE = new URL("./", BASE).href;
const precached = new Set(PRECACHE.map((p) => new URL(p, BASE).href));

self.addEventListener("install", (event) => {
  // no skipWaiting: a new version waits until no tab of the old one is open (used from the next visit)
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      await Promise.all(
        PRECACHE.map(async (p) => {
          const url = new URL(p, BASE).href;
          // hashed files never change (the browser's copy is good); the page and the rest are checked
          const res = await fetch(url, { cache: HASHED(p) ? "default" : "no-cache", credentials: "same-origin" });
          if (!res.ok) throw new Error(url + " " + res.status);
          await cache.put(url, res);
        }),
      );
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith("nukcad-app-") && key !== CACHE) await caches.delete(key);
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  // this site's own files under the app's folder only (map tiles, AI models … as before)
  if (url.origin !== BASE.origin || !url.pathname.startsWith(BASE.pathname)) return;
  if (url.pathname.endsWith("/" + "sw.js")) return;
  if (req.mode === "navigate" && (url.pathname === BASE.pathname || url.pathname === BASE.pathname + "index.html")) {
    // the page of this version (with any ?… after it), the network when it is not kept
    event.respondWith((async () => (await caches.match(PAGE, { cacheName: CACHE })) || fetch(req))());
    return;
  }
  url.search = "";
  url.hash = "";
  const key = url.href;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(key);
      if (hit) return hit;
      const res = await fetch(req);
      // a file of this version not fetched ahead (the AI's): kept once used
      if (res.ok && res.type === "basic" && !precached.has(key) && HASHED(key.slice(BASE.href.length))) cache.put(key, res.clone()).catch(() => {});
      return res;
    })(),
  );
});
